function hydroMeta(gid){for(const a of Object.values(D.sixNode.hydroAssets||{})){const m=(a.metadata||[]).find(x=>x.Generator===gid);if(m)return m}return {Generator:gid,PlantName:gid,Class:'Hydro',Status:'',HydroRegime:''}}
