    if(i<nodes.length-1){const down=nodes[i+1],flow=down.rv&&Object.keys(down.rv).length?n(down.rv.UpstreamRelease_Hm3):n(down.cv.UpstreamRelease_Hm3);parts.push(`<div class="cascade-arrow"><span class="shaft">→</span><span class="flow-unit">${fmt(flow,1)} hm³</span><span class="flow-label">upstream water transferred in ${monthNames[state.month-1]}</span></div>`)}
